  b('reduction-intro','paragraph',3,16,'وتحدث عملية اختزال خام الحديد في سلسلة من الخطوات، انظر الشكل (1-1) تجد أنه بقرب قمة الفرن يتم اختزال Fe₂O₃ إلى Fe₃O₄، كما في المعادلة الآتية:','<p>وتحدث عملية اختزال خام الحديد في سلسلة من الخطوات، انظر الشكل (1-1) تجد أنه بقرب قمة الفرن يتم اختزال Fe<sub>2</sub>O<sub>3</sub> إلى Fe<sub>3</sub>O<sub>4</sub>، كما في المعادلة الآتية:</p>'),
  formula('hematite-reduction',3,16,'3Fe₂O₃ + CO → 2Fe₃O₄ + CO₂','3Fe<sub>2</sub>O<sub>3</sub> + CO → 2Fe<sub>3</sub>O<sub>4</sub> + CO<sub>2</sub>'),
  b('magnetite-reduction-intro','paragraph',3,16,'وإلى أسفل من ذلك بقليل، في منطقة أكثر حرارة من الفرن، يختزل Fe₃O₄ إلى FeO، حسب المعادلة الآتية:','<p>وإلى أسفل من ذلك بقليل، في منطقة أكثر حرارة من الفرن، يختزل Fe<sub>3</sub>O<sub>4</sub> إلى FeO، حسب المعادلة الآتية:</p>'),
