 return f'<section id="officialBookContent" data-layer="A_OFFICIAL_TEXTBOOK" data-official-standard="20A" dir="rtl" data-source-file-hash="sha256:{h}">'+''.join(f'<section data-block-id="{b["id"]}" data-block-type="{b["type"]}" data-source-page="{b["source_page"]}" data-printed-page="{b["printed_page"]}">{b["html"]}</section>' for b in bs)+'</section>'

